   746  /**
   747   * Advances *optp to next option if still in PDU. This function
   748   * returns the number of bytes opt has been advanced or @c 0
   749   * on error.
   750   */
   751  static size_t
   752  next_option_safe(coap_opt_t **optp, size_t *length, uint16_t *max_opt) {
   753    coap_option_t option;
   754    size_t optsize;
   755
   756    assert(optp); assert(*optp);
   757    assert(length);
   758
   759    optsize = coap_opt_parse(*optp, *length, &option);
   760    if (optsize) {
   761      assert(optsize <= *length);
   762
   763      /* signal an error if this option would exceed the
   764       * allowed number space */
   765      if (*max_opt + option.delta > COAP_MAX_OPT) {
   766        return 0;
   767      }
   768      *max_opt += option.delta;
   769      *optp += optsize;
   770      *length -= optsize;
   771    }
   772
   773    return optsize;
   774  }
